/**
 * Normalizes track titles for fuzzy matching across search engines,
 * stripping movie/album suffixes, subtitles, feature tags, and punctuation.
 */
export function normalizeTrackName(name) {
  if (!name) return '';
  return name
    .toLowerCase()
    .replace(/\(.*?\)/g, '')
    .replace(/\[.*?\]/g, '')
    .replace(/[-–—].*$/, '')
    .replace(/[^a-z0-9]/g, '')
    .trim();
}

/**
 * Normalizes artist names for fuzzy matching,
 * stripping "feat.", "ft.", collaborations, and punctuation.
 */
export function normalizeArtistName(name) {
  if (!name) return '';
  return name
    .toLowerCase()
    .replace(/ft\..*$/i, '')
    .replace(/feat\..*$/i, '')
    .replace(/\(.*?\)/g, '')
    .replace(/[^a-z0-9]/g, '')
    .trim();
}

/**
 * Intelligently binds any incoming searched or played track to our 100% verified
 * CURATED_TRACKS catalog master with word-by-word synced lyrics.
 */
export function findCuratedTrack(target) {
  if (!target) return null;
  if (target.id) {
    const byId = CURATED_TRACKS.find(ct => ct.id === target.id);
    if (byId) return byId;
  }

  const targetTitleNorm = normalizeTrackName(target.title);
  if (!targetTitleNorm) return null;

  const targetArtistNorm = normalizeArtistName(target.artist);

  // 1. Exact normalized title match
  for (const ct of CURATED_TRACKS) {
    const ctTitleNorm = normalizeTrackName(ct.title);
    if (ctTitleNorm === targetTitleNorm) {
      return ct;
    }
  }

  // 2. Substring/prefix title match with artist validation
  for (const ct of CURATED_TRACKS) {
    const ctTitleNorm = normalizeTrackName(ct.title);
    if (
      (targetTitleNorm.length >= 3 && ctTitleNorm.includes(targetTitleNorm)) ||
      (ctTitleNorm.length >= 3 && targetTitleNorm.includes(ctTitleNorm))
    ) {
      const ctArtistNorm = normalizeArtistName(ct.artist);
      if (!targetArtistNorm || ctArtistNorm.includes(targetArtistNorm) || targetArtistNorm.includes(ctArtistNorm)) {
        return ct;
      }
    }
  }

  return null;
}

